#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_copy_stack_successful_copy(void) {
    // Setup: create a source stack with some elements
    DArrayStack *src = create_stack(10);
    TEST_ASSERT_NOT_NULL(src);

    // Push some values onto the source stack
    int values[] = {5, 10, 15, 20};
    for (int i = 0; i < 4; i++) {
        push(src, values[i]);
    }

    // Test: create a deep copy
    DArrayStack *dest = copy_stack(src);
    if (dest == NULL) {
        free_stack(src);
        TEST_FAIL_MESSAGE("copy_stack returned NULL");
    }

    // Assertions
    TEST_ASSERT_NOT_NULL(dest);
    TEST_ASSERT_NOT_EQUAL(src, dest); // Should be different pointers
    TEST_ASSERT_EQUAL_INT(src->capacity, dest->capacity);
    TEST_ASSERT_EQUAL_INT(src->top, dest->top);

    // Verify all elements were copied
    for (int i = 0; i <= src->top; i++) {
        TEST_ASSERT_EQUAL_INT(src->arrPtr[i], dest->arrPtr[i]);
    }

    // Verify independence: modify source, ensure dest unchanged
    push(src, 99);
    TEST_ASSERT_EQUAL_INT(4, dest->top); // dest top should still be 3 (0-indexed)
    TEST_ASSERT_EQUAL_INT(20, dest->arrPtr[dest->top]); // Last element unchanged

    // Cleanup
    free_stack(src);
    free_stack(dest);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_copy_stack_successful_copy);
    return UNITY_END();
}

